test('lineBulkDiscount with zero line discount', () => {
  const line = { qty: 10, unitPrice: 5000, discountPercent: 0 };
  // lineTotal = 50000, lineDiscount = 0
  // bulkDiscount = 50000 * 2.5 / 100 = 1250
  assert.equal(lineBulkDiscount(line), 1250);
});

test('lineBulkDiscount with high line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 50 };
  // lineTotal = 10000, lineDiscount = 5000
  // bulkDiscount = 5000 * 2.5 / 100 = 125
  assert.equal(lineBulkDiscount(line), 125);
});

test('lineBulkDiscount with missing discountPercent', () => {
  const line = { qty: 10, unitPrice: 1000 };
  // lineTotal = 10000, lineDiscount = 0 (missing discount)
  // bulkDiscount = 10000 * 2.5 / 100 = 250
  assert.equal(lineBulkDiscount(line), 250);
});

test('invoiceTotals with multiple lines some qualifying for bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
      { qty: 10, unitPrice: 2000, discountPercent: 0, vatRate: 21 },
      { qty: 8, unitPrice: 1500, discountPercent: 10, vatRate: 9 },
      { qty: 12, unitPrice: 1000, discountPercent: 5, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: total=5000, discount=250, bulk=0, after=4750, vat=997
  // Line 2: total=20000, discount=0, bulk=500, after=19500, vat=4095
  // Line 3: total=12000, discount=1200, bulk=0, after=10800, vat=972
  // Line 4: total=12000, discount=600, bulk=287, after=11113, vat=0
  // Subtotal = 49000
  // Total discount = 250 + 0 + 1200 + 600 + 0 + 500 + 0 + 287 = 2837
  // Total VAT = 997 + 4095 + 972 + 0 = 6064
  // Total = 49000 - 2837 + 6064 = 52227
  assert.equal(totals.subtotal, 49000);
  assert.equal(totals.discount, 2837);
  assert.equal(totals.vat, 6064);
  assert.equal(totals.total, 52227);
});

test('bulk discount affects only qty >= 10', () => {
  const line9 = { qty: 9, unitPrice: 10000, discountPercent: 0 };
  const line10 = { qty: 10, unitPrice: 10000, discountPercent: 0 };
  assert.equal(lineBulkDiscount(line9), 0);
  assert.equal(lineBulkDiscount(line10), 2500);
});

test('lineVat no bulk discount for qty < 10', () => {
