  // lineTotal = 10000, lineDiscount = 1000
  // After line discount = 9000, bulkDiscount = 225
  // After all discounts = 9000 - 225 = 8775
  // VAT = 8775 * 21 / 100 = 1842.75, rounds to 1843
  assert.equal(lineVat(line), 1843);
});

test('invoiceTotals includes bulk discount in total discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal = 10000
  // Discount = 0 (line) + 250 (bulk) = 250
  // VAT = 0
  // Total = 10000 - 250 + 0 = 9750
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 9750);
});

test('invoiceTotals with mixed bulk discount lines', () => {
