  const totals = invoiceTotals(invoice);
  // Line 1: total = 5000, discount = 0, bulk = 0
  // Line 2: total = 10000, discount = 0, bulk = 250
  // Line 3: total = 20000, discount = 0, bulk = 500
  // Subtotal = 35000
  // Total discount = 0 + 0 + 0 + 250 + 500 = 750
  // VAT = 0
  // Total = 35000 - 750 + 0 = 34250
  assert.equal(totals.subtotal, 35000);
  assert.equal(totals.discount, 750);
  assert.equal(totals.total, 34250);
});

test('invoiceTotals with bulk discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal = 10000
  // Discount = 0 + 250 = 250
  // After discount = 9750
  // VAT = 9750 * 21 / 100 = 2047.5 rounds to 2048
  // Total = 10000 - 250 + 2048 = 11798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 11798);
});

